/**
 * Book storage backed by a single JSON file.
 *
 * The whole list lives in memory; every mutation writes the file back out. Writes
 * are queued so two overlapping requests can't interleave, and each one goes to a
 * temp file that is renamed into place, so an interrupted write leaves the previous
 * file intact rather than a half-written one.
 */

import { randomBytes } from 'node:crypto';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';

export const READING = 'reading';
export const FINISHED = 'finished';

const DEFAULT_FILE = 'data/books.json';

/** Open (and create, on first write) the store at `file`. */
export async function openStore(file = process.env.BOOKS_FILE ?? DEFAULT_FILE) {
  const path = resolve(file);
  return new BookStore(path, await readBooks(path));
}

export class BookStore {
  #path;
  #books;
  #queue = Promise.resolve();

  constructor(path, books) {
    this.#path = path;
    this.#books = books;
  }

  get path() {
    return this.#path;
  }

  /** Books still being read, most recently added first. */
  reading() {
    return this.#books
      .filter((b) => b.status === READING)
      .sort((a, b) => b.addedAt.localeCompare(a.addedAt));
  }

  /** Books finished, most recently finished first. */
  finished() {
    return this.#books
      .filter((b) => b.status === FINISHED)
      .sort((a, b) => (b.finishedAt ?? '').localeCompare(a.finishedAt ?? ''));
  }

  get(id) {
    return this.#books.find((b) => b.id === id) ?? null;
  }

  /**
   * Add a book. Only the title is required; author and notes may be blank.
   * Throws ValidationError if the title is missing.
   */
  async add({ title, author, notes } = {}) {
    const cleanTitle = clean(title);
    if (!cleanTitle) throw new ValidationError('A book needs a title.');

    const book = {
      id: makeId(cleanTitle, new Set(this.#books.map((b) => b.id))),
      title: cleanTitle,
      author: clean(author),
      notes: clean(notes),
      status: READING,
      addedAt: new Date().toISOString(),
      finishedAt: null,
    };
    this.#books.push(book);
    await this.#save();
    return book;
  }

  /**
   * Mark a book finished. Returns the book, or null if there is no such book.
   * Finishing an already-finished book leaves the original date alone.
   */
  async finish(id) {
    const book = this.get(id);
    if (!book) return null;
    if (book.status === FINISHED) return book;

    book.status = FINISHED;
    book.finishedAt = new Date().toISOString();
    await this.#save();
    return book;
  }

  /** Wait for any in-flight write to land. */
  flush() {
    return this.#queue;
  }

  #save() {
    // Chain onto the queue so writes never overlap, and swallow nothing: the
    // caller awaits the same promise and sees any failure.
    this.#queue = this.#queue.then(
      () => this.#writeFile(),
      () => this.#writeFile()
    );
    return this.#queue;
  }

  async #writeFile() {
    const body = JSON.stringify({ books: this.#books }, null, 2) + '\n';
    const tmp = `${this.#path}.${process.pid}.tmp`;
    await mkdir(dirname(this.#path), { recursive: true });
    await writeFile(tmp, body, 'utf8');
    await rename(tmp, this.#path);
  }
}

export class ValidationError extends Error {}

async function readBooks(path) {
  let raw;
  try {
    raw = await readFile(path, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return []; // First run.
    throw err;
  }
  if (!raw.trim()) return [];

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    throw new Error(
      `${path} is not valid JSON (${err.message}). Fix or move the file aside to start fresh.`
    );
  }

  const books = Array.isArray(parsed) ? parsed : parsed?.books;
  if (!Array.isArray(books)) {
    throw new Error(`${path} does not contain a book list. Expected {"books": [...]}.`);
  }
  return books.filter((b) => b && typeof b === 'object').map(normalise);
}

/** Fill in anything a hand-edited or older file might be missing. */
function normalise(book, index) {
  const title = clean(book.title) || 'Untitled';
  const status = book.status === FINISHED ? FINISHED : READING;
  return {
    id: clean(book.id) || `book-${index + 1}`,
    title,
    author: clean(book.author),
    notes: clean(book.notes),
    status,
    addedAt: clean(book.addedAt) || new Date(0).toISOString(),
    finishedAt: status === FINISHED ? clean(book.finishedAt) || null : null,
  };
}

/**
 * Readable id, so a shared link says what it points at: "the-hobbit-4f9a".
 * The random suffix keeps two books of the same name apart.
 */
function makeId(title, taken) {
  const slug =
    title
      .toLowerCase()
      .normalize('NFKD')
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
      .slice(0, 40)
      .replace(/-+$/, '') || 'book';

  let id;
  do {
    id = `${slug}-${randomBytes(2).toString('hex')}`;
  } while (taken.has(id));
  return id;
}

function clean(value) {
  return typeof value === 'string' ? value.trim() : '';
}

