/** HTML rendering. Every value that comes from a book goes through escape(). */

import { FINISHED } from './store.js';

export function escape(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function layout({ title, body }) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escape(title)}</title>
<link rel="stylesheet" href="/style.css">
</head>
<body>
<main>
${body}
</main>
</body>
</html>
`;
}

/** The home page: what I'm reading, what I've finished, and the add form. */
export function listPage({ reading, finished, error }) {
  return layout({
    title: 'Bookshelf',
    body: `<h1>Bookshelf</h1>

${error ? `<p class="error" role="alert">${escape(error)}</p>` : ''}

<section>
  <h2>Currently reading <span class="count">${reading.length}</span></h2>
  ${
    reading.length
      ? `<ul class="books">${reading.map(readingItem).join('\n')}</ul>`
      : `<p class="empty">Nothing on the go. Add a book below.</p>`
  }
</section>

<section>
  <h2>Finished <span class="count">${finished.length}</span></h2>
  ${
    finished.length
      ? `<ul class="books">${finished.map(finishedItem).join('\n')}</ul>`
      : `<p class="empty">No finished books yet.</p>`
  }
</section>

<section class="add">
  <h2>Add a book</h2>
  <form method="post" action="/books">
    <label>
      Title
      <input name="title" required autocomplete="off" value="${escape(error ? '' : '')}">
    </label>
    <label>
      Author
      <input name="author" autocomplete="off">
    </label>
    <label>
      Notes <span class="hint">optional</span>
      <textarea name="notes" rows="3"></textarea>
    </label>
    <button type="submit">Add book</button>
  </form>
</section>
`,
  });
}

function readingItem(book) {
  return `<li>
  <a class="book-link" href="/books/${escape(book.id)}">
    <span class="book-title">${escape(book.title)}</span>
    <span class="book-author">${escape(byline(book))}</span>
  </a>
  <form method="post" action="/books/${escape(book.id)}/finish">
    <button type="submit" class="secondary">Mark finished</button>
  </form>
</li>`;
}

function finishedItem(book) {
  return `<li>
  <a class="book-link" href="/books/${escape(book.id)}">
    <span class="book-title">${escape(book.title)}</span>
    <span class="book-author">${escape(byline(book))}</span>
  </a>
  <span class="date">${escape(formatDate(book.finishedAt))}</span>
</li>`;
}

/** A single book: title, author, notes, and a link to share. */
export function bookPage({ book, shareUrl }) {
  const done = book.status === FINISHED;
  return layout({
    title: `${book.title} — Bookshelf`,
    body: `<p class="back"><a href="/">&larr; Bookshelf</a></p>

<article>
  <h1>${escape(book.title)}</h1>
  <p class="byline">${escape(byline(book))}</p>

  <p class="status ${done ? 'done' : 'reading'}">
    ${
      done
        ? `Finished ${escape(formatDate(book.finishedAt))}`
        : `Currently reading &middot; added ${escape(formatDate(book.addedAt))}`
    }
  </p>

  <h2>Notes</h2>
  ${
    book.notes
      ? `<p class="notes">${escape(book.notes)}</p>`
      : `<p class="empty">No notes yet.</p>`
  }

  ${
    done
      ? ''
      : `<form method="post" action="/books/${escape(book.id)}/finish">
    <button type="submit">Mark finished</button>
  </form>`
  }

  <section class="share">
    <h2>Share this book</h2>
    <p class="share-url"><code id="share-url">${escape(shareUrl)}</code></p>
    <button type="button" id="copy" hidden>Copy link</button>
  </section>
</article>

<script>
  // Convenience only — the link above is selectable without it.
  const button = document.getElementById('copy');
  if (navigator.clipboard) {
    button.hidden = false;
    button.addEventListener('click', async () => {
      await navigator.clipboard.writeText(document.getElementById('share-url').textContent);
      button.textContent = 'Copied';
      setTimeout(() => { button.textContent = 'Copy link'; }, 1500);
    });
  }
</script>
`,
  });
}

export function notFoundPage() {
  return layout({
    title: 'Not found — Bookshelf',
    body: `<h1>Not found</h1>
<p class="empty">That book isn't on the shelf.</p>
<p class="back"><a href="/">&larr; Bookshelf</a></p>
`,
  });
}

export function errorPage(message) {
  return layout({
    title: 'Something went wrong — Bookshelf',
    body: `<h1>Something went wrong</h1>
<p class="error">${escape(message)}</p>
<p class="back"><a href="/">&larr; Bookshelf</a></p>
`,
  });
}

function byline(book) {
  return book.author || 'Unknown author';
}

function formatDate(iso) {
  if (!iso) return '';
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return '';
  return date.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
}

