/**
 * Routes:
 *   GET  /                    home — currently reading + finished + add form
 *   POST /books               add a book, then redirect home
 *   GET  /books/:id           one book: title, author, notes, shareable link
 *   POST /books/:id/finish    mark finished, then redirect back
 *   GET  /style.css
 */

import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

import { ValidationError } from './store.js';
import { bookPage, errorPage, listPage, notFoundPage } from './views.js';

const CSS_PATH = fileURLToPath(new URL('../public/style.css', import.meta.url));
const MAX_BODY_BYTES = 64 * 1024;

export function createApp(store) {
  return createServer((req, res) => {
    handle(req, res, store).catch((err) => {
      console.error(err);
      if (!res.headersSent) {
        send(res, 500, errorPage('Sorry — the shelf fell over. Check the server log.'));
      } else {
        res.end();
      }
    });
  });
}

async function handle(req, res, store) {
  const url = new URL(req.url, `http://${req.headers.host ?? 'localhost'}`);
  const path = url.pathname.replace(/\/+$/, '') || '/';
  const method = req.method === 'HEAD' ? 'GET' : req.method;

  if (method === 'GET' && path === '/') {
    return send(
      res,
      200,
      listPage({
        reading: store.reading(),
        finished: store.finished(),
        error: errorMessage(url.searchParams.get('error')),
      })
    );
  }

  if (method === 'GET' && path === '/style.css') {
    return send(res, 200, await css(), 'text/css; charset=utf-8');
  }

  if (method === 'POST' && path === '/books') {
    const form = await readForm(req);
    try {
      const book = await store.add({
        title: form.get('title'),
        author: form.get('author'),
        notes: form.get('notes'),
      });
      return redirect(res, `/books/${encodeURIComponent(book.id)}`);
    } catch (err) {
      if (err instanceof ValidationError) return redirect(res, '/?error=missing-title');
      throw err;
    }
  }

  const finish = path.match(/^\/books\/([^/]+)\/finish$/);
  if (finish && method === 'POST') {
    const book = await store.finish(decodeURIComponent(finish[1]));
    if (!book) return send(res, 404, notFoundPage());
    // Back to wherever the button was pressed, so finishing from a book page
    // stays on that book.
    return redirect(res, backTo(req, book.id));
  }

  const detail = path.match(/^\/books\/([^/]+)$/);
  if (detail && method === 'GET') {
    const book = store.get(decodeURIComponent(detail[1]));
    if (!book) return send(res, 404, notFoundPage());
    return send(res, 200, bookPage({ book, shareUrl: new URL(`/books/${book.id}`, url).href }));
  }

  if (method !== 'GET' && method !== 'POST') {
    res.writeHead(405, { Allow: 'GET, HEAD, POST' });
    return res.end();
  }

  return send(res, 404, notFoundPage());
}

/** Where to go after marking a book finished. */
function backTo(req, id) {
  const referer = req.headers.referer;
  if (referer) {
    try {
      const from = new URL(referer, `http://${req.headers.host ?? 'localhost'}`);
      if (from.pathname === `/books/${id}`) return from.pathname;
    } catch {
      // Unparseable Referer — fall through to the shelf.
    }
  }
  return '/';
}

function errorMessage(code) {
  return code === 'missing-title' ? 'A book needs a title.' : '';
}

async function readForm(req) {
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY_BYTES) {
      req.destroy();
      throw new Error('Form submission too large.');
    }
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

function send(res, status, body, contentType = 'text/html; charset=utf-8') {
  res.writeHead(status, {
    'Content-Type': contentType,
    'Content-Length': Buffer.byteLength(body),
    'Cache-Control': 'no-store',
  });
  res.end(body);
}

/** 303 so the browser follows up with a GET and reloads don't re-post the form. */
function redirect(res, location) {
  res.writeHead(303, { Location: location, 'Content-Length': 0 });
  res.end();
}

let cssCache;
function css() {
  cssCache ??= readFile(CSS_PATH, 'utf8');
  return cssCache;
}

