:root {
  color-scheme: light dark;
  --bg: #fbfaf7;
  --panel: #ffffff;
  --text: #1d1c1a;
  --muted: #6b6864;
  --line: #e5e1d9;
  --accent: #7a4b2a;
  --danger: #a3341f;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #171614;
    --panel: #201e1b;
    --text: #ece9e3;
    --muted: #a09c95;
    --line: #322f2b;
    --accent: #d8a87c;
    --danger: #e8836a;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 2.5rem 1.25rem 4rem;
  background: var(--bg);
  color: var(--text);
  font: 16px/1.6 ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

main {
  max-width: 44rem;
  margin: 0 auto;
}

h1 {
  margin: 0 0 1.5rem;
  font-size: 1.9rem;
  letter-spacing: -0.02em;
}

h2 {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin: 0 0 0.75rem;
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
}

section {
  margin-bottom: 2.5rem;
}

.count {
  padding: 0.05rem 0.45rem;
  border: 1px solid var(--line);
  border-radius: 999px;
  font-size: 0.7rem;
  letter-spacing: 0;
}

.empty {
  margin: 0;
  color: var(--muted);
}

.hint {
  font-weight: 400;
  text-transform: none;
