import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';

import { FINISHED, READING, ValidationError, openStore } from '../src/store.js';

let dir;
let file;

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'bookshelf-'));
  file = join(dir, 'books.json');
});

afterEach(async () => {
  await rm(dir, { recursive: true, force: true });
});

describe('openStore', () => {
  it('starts empty when the file does not exist yet', async () => {
    const store = await openStore(file);
    expect(store.reading()).toEqual([]);
    expect(store.finished()).toEqual([]);
  });

  it('creates the file (and its directory) on first write', async () => {
    const nested = join(dir, 'data', 'books.json');
    const store = await openStore(nested);
    await store.add({ title: 'Dune' });

    const saved = JSON.parse(await readFile(nested, 'utf8'));
    expect(saved.books).toHaveLength(1);
  });

  it('reads books back after a restart', async () => {
    const first = await openStore(file);
    const book = await first.add({ title: 'The Hobbit', author: 'Tolkien', notes: 'Cosy.' });
    await first.finish(book.id);

    const second = await openStore(file);
    expect(second.get(book.id)).toMatchObject({
      title: 'The Hobbit',
      author: 'Tolkien',
      notes: 'Cosy.',
      status: FINISHED,
    });
  });

  it('fills in fields missing from a hand-edited file', async () => {
    await writeFile(file, JSON.stringify({ books: [{ title: 'Sparse' }] }));
    const store = await openStore(file);

    expect(store.reading()[0]).toMatchObject({ title: 'Sparse', author: '', status: READING });
    expect(store.reading()[0].id).toBeTruthy();
  });

  it('accepts a bare array as well as {books: [...]}', async () => {
    await writeFile(file, JSON.stringify([{ id: 'a', title: 'Bare' }]));
    const store = await openStore(file);
    expect(store.get('a').title).toBe('Bare');
  });

  it('refuses to start on a corrupt file rather than losing it', async () => {
    await writeFile(file, '{ not json');
    await expect(openStore(file)).rejects.toThrow(/not valid JSON/);
  });
});

describe('add', () => {
  it('adds a book as currently reading', async () => {
    const store = await openStore(file);
    const book = await store.add({ title: 'Piranesi', author: 'Susanna Clarke' });

    expect(book.status).toBe(READING);
    expect(book.finishedAt).toBeNull();
    expect(store.reading().map((b) => b.id)).toEqual([book.id]);
    expect(store.finished()).toEqual([]);
  });

  it('trims input and requires a title', async () => {
    const store = await openStore(file);
    const book = await store.add({ title: '  Ulysses  ', author: '  Joyce ' });
    expect(book).toMatchObject({ title: 'Ulysses', author: 'Joyce' });

    await expect(store.add({ title: '   ' })).rejects.toThrow(ValidationError);
    await expect(store.add({})).rejects.toThrow(ValidationError);
    expect(store.reading()).toHaveLength(1);
  });

  it('gives each book a readable, unique id', async () => {
    const store = await openStore(file);
    const one = await store.add({ title: 'The Hobbit!' });
    const two = await store.add({ title: 'The Hobbit!' });

    expect(one.id).toMatch(/^the-hobbit-[0-9a-f]{4}$/);
    expect(two.id).not.toBe(one.id);
  });

  it('keeps concurrent adds from clobbering each other on disk', async () => {
    const store = await openStore(file);
    await Promise.all(
      Array.from({ length: 10 }, (_, i) => store.add({ title: `Book ${i}` }))
    );
    await store.flush();

    const saved = JSON.parse(await readFile(file, 'utf8'));
    expect(saved.books).toHaveLength(10);
  });
});

describe('finish', () => {
  it('moves a book to finished with a date', async () => {
    const store = await openStore(file);
    const book = await store.add({ title: 'Stoner' });

    const finished = await store.finish(book.id);
    expect(finished.status).toBe(FINISHED);
    expect(Date.parse(finished.finishedAt)).not.toBeNaN();
    expect(store.reading()).toEqual([]);
    expect(store.finished().map((b) => b.id)).toEqual([book.id]);
  });

  it('is a no-op for an already finished book', async () => {
    const store = await openStore(file);
    const book = await store.add({ title: 'Stoner' });
    const first = await store.finish(book.id);
    const again = await store.finish(book.id);
    expect(again.finishedAt).toBe(first.finishedAt);
  });

  it('returns null for an unknown id', async () => {
    const store = await openStore(file);
    expect(await store.finish('nope')).toBeNull();
    expect(store.get('nope')).toBeNull();
  });
});

describe('ordering', () => {
  it('lists newest first in both sections', async () => {
    const store = await openStore(file);
    const a = await store.add({ title: 'A' });
    const b = await store.add({ title: 'B' });
    const c = await store.add({ title: 'C' });

    // Same-millisecond timestamps would make this flaky, so space them out.
    a.addedAt = '2024-01-01T00:00:00.000Z';
    b.addedAt = '2024-02-01T00:00:00.000Z';
    c.addedAt = '2024-03-01T00:00:00.000Z';
    expect(store.reading().map((x) => x.title)).toEqual(['C', 'B', 'A']);

    await store.finish(a.id);
    await store.finish(b.id);
    a.finishedAt = '2024-04-01T00:00:00.000Z';
    b.finishedAt = '2024-05-01T00:00:00.000Z';
    expect(store.finished().map((x) => x.title)).toEqual(['B', 'A']);
  });
});

