/** Submit the add-book form the way a browser would. */
function addBook(fields, options = {}) {
  return fetch(`${base}/books`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams(fields),
    redirect: 'manual',
    ...options,
  });
}

describe('GET /', () => {
  it('shows both sections and the add form when empty', async () => {
    const html = await (await fetch(base)).text();
    expect(html).toContain('Currently reading');
    expect(html).toContain('Finished');
    expect(html).toContain('Nothing on the go');
    expect(html).toContain('<form method="post" action="/books">');
  });

  it('lists reading and finished books in their own sections', async () => {
    const reading = await store.add({ title: 'Piranesi', author: 'Susanna Clarke' });
    const done = await store.add({ title: 'Stoner', author: 'John Williams' });
    await store.finish(done.id);

    const html = await (await fetch(base)).text();
    const readingSection = html.slice(
      html.indexOf('Currently reading'),
      html.indexOf('Finished <span')
    );
    const finishedSection = html.slice(html.indexOf('Finished <span'));

    expect(readingSection).toContain(`/books/${reading.id}`);
    expect(readingSection).toContain('Mark finished');
    expect(finishedSection).toContain(`/books/${done.id}`);
    expect(finishedSection).not.toContain('Mark finished');
  });

  it('serves the stylesheet it links to', async () => {
    const res = await fetch(`${base}/style.css`);
    expect(res.status).toBe(200);
    expect(res.headers.get('content-type')).toMatch(/text\/css/);
  });
});

describe('POST /books', () => {
  it('adds a book and redirects home', async () => {
    const res = await addBook({ title: 'Dune', author: 'Frank Herbert', notes: 'Sand.' });

    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/');
    expect(store.reading()).toHaveLength(1);
    expect(store.reading()[0]).toMatchObject({
      title: 'Dune',
      author: 'Frank Herbert',
      notes: 'Sand.',
    });
  });

  it('accepts a book with no author or notes', async () => {
    await addBook({ title: 'Just a title' });
    expect(store.reading()[0]).toMatchObject({ title: 'Just a title', author: '', notes: '' });
  });

  it('reports a missing title instead of adding a blank book', async () => {
    const res = await addBook({ title: '  ', author: 'Nobody' });
    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/?error=missing-title');
    expect(store.reading()).toHaveLength(0);

    const html = await (await fetch(`${base}/?error=missing-title`)).text();
    expect(html).toContain('A book needs a title.');
  });
});

describe('GET /books/:id', () => {
  it('shows title, author, notes and a shareable link', async () => {
    const book = await store.add({
      title: 'Piranesi',
      author: 'Susanna Clarke',
      notes: 'Line one\nLine two',
    });

    const res = await fetch(`${base}/books/${book.id}`);
    const html = await res.text();

    expect(res.status).toBe(200);
    expect(html).toContain('Piranesi');
    expect(html).toContain('Susanna Clarke');
    expect(html).toContain('Line one\nLine two');
    expect(html).toContain(`${base}/books/${book.id}`);
  });

  it('works as a standalone link with no session or referer', async () => {
    const book = await store.add({ title: 'Shared Book' });
    const res = await fetch(`${base}/books/${book.id}`, { headers: { Cookie: '' } });
    expect(res.status).toBe(200);
    expect(await res.text()).toContain('Shared Book');
  });

  it('says so when there are no notes', async () => {
    const book = await store.add({ title: 'No Notes' });
    expect(await (await fetch(`${base}/books/${book.id}`)).text()).toContain('No notes yet.');
  });

  it('404s for an unknown book', async () => {
    const res = await fetch(`${base}/books/does-not-exist`);
    expect(res.status).toBe(404);
    expect(await res.text()).toContain("isn't on the shelf");
  });

  it('escapes book text instead of rendering it as HTML', async () => {
    const book = await store.add({
      title: '<script>alert(1)</script>',
      author: '"quoted" & <b>bold</b>',
      notes: '<img src=x onerror=alert(2)>',
    });

    const html = await (await fetch(`${base}/books/${book.id}`)).text();
    expect(html).not.toContain('<script>alert(1)</script>');
    expect(html).not.toContain('<img src=x');
    expect(html).toContain('&lt;script&gt;alert(1)&lt;/script&gt;');
    expect(html).toContain('&amp;');
  });
});

describe('POST /books/:id/finish', () => {
  it('marks the book finished and returns to the shelf', async () => {
    const book = await store.add({ title: 'Stoner' });

    const res = await fetch(`${base}/books/${book.id}/finish`, {
      method: 'POST',
      redirect: 'manual',
    });

    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/');
    expect(store.finished().map((b) => b.id)).toEqual([book.id]);
  });

  it('stays on the book page when finished from there', async () => {
    const book = await store.add({ title: 'Stoner' });

    const res = await fetch(`${base}/books/${book.id}/finish`, {
      method: 'POST',
      headers: { Referer: `${base}/books/${book.id}` },
      redirect: 'manual',
    });

    expect(res.headers.get('location')).toBe(`/books/${book.id}`);
    const html = await (await fetch(`${base}/books/${book.id}`)).text();
    expect(html).toContain('Finished');
    expect(html).not.toContain('Mark finished');
  });

  it('survives a restart', async () => {
    const book = await store.add({ title: 'Stoner' });
    await fetch(`${base}/books/${book.id}/finish`, { method: 'POST', redirect: 'manual' });

    const reopened = await openStore(store.path);
    expect(reopened.finished().map((b) => b.title)).toEqual(['Stoner']);
  });

  it('404s for an unknown book', async () => {
    const res = await fetch(`${base}/books/nope/finish`, { method: 'POST', redirect: 'manual' });
    expect(res.status).toBe(404);
  });
});

describe('other requests', () => {
  it('404s unknown paths', async () => {
    expect((await fetch(`${base}/nope`)).status).toBe(404);
  });

  it('rejects methods it does not handle', async () => {
    const res = await fetch(`${base}/books`, { method: 'DELETE' });
    expect(res.status).toBe(405);
    expect(res.headers.get('allow')).toContain('GET');
  });
});

